SELECT AVG(q) AS v FROM (SELECT oi.order_id, SUM(oi.quantity) AS q FROM order_items oi WHERE oi.order_id IN (SELECT o.order_id FROM orders o WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2024-07-01 00:00:00' AND o.order_at < TIMESTAMP '2024-10-01 00:00:00') GROUP BY oi.order_id) t
